#[cfg(not(target_os="macos"))]mod native{
use winit::{application::ApplicationHandler,event::{WindowEvent,ElementState,MouseButton,DeviceId},event_loop::{ActiveEventLoop,EventLoop},window::Window,keyboard::ModifiersState,dpi::{LogicalSize,PhysicalPosition}};
use ingetrazo_gui::{IngeTrazoApp,navigation::{self,Mode},pointer_modifiers};use glam::DVec3;
fn ui(app:&mut IngeTrazoApp,ctx:&egui::Context,input:egui::RawInput){let _=ctx.run(input,|ctx|{egui::CentralPanel::default().frame(egui::Frame::none()).show(ctx,|ui|{let rect=ui.available_rect_before_wrap();let response=ui.allocate_rect(rect,egui::Sense::click_and_drag());navigation::input(app,ui,rect,&response);});});}
struct Probe;
impl ApplicationHandler for Probe{fn resumed(&mut self,event_loop:&ActiveEventLoop){let mut rows=vec![];for snapshots in [false,true]{
let window=event_loop.create_window(Window::default_attributes().with_title("Owned Walk ingress diagnostic").with_inner_size(LogicalSize::new(800.,600.)).with_visible(false)).unwrap();let ctx=egui::Context::default();let mut app=IngeTrazoApp::new();app.camera.aspect=800./600.;app.camera.distance=10.;app.camera.look_from(DVec3::new(0.,0.,1.68),DVec3::Y);app.activate_navigation(Mode::Walk);
ui(&mut app,&ctx,egui::RawInput{screen_rect:Some(egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(800.,600.))),time:Some(0.),focused:true,..Default::default()});let handle=if snapshots{Some(pointer_modifiers::install(&ctx))}else{None};let mut state=egui_winit::State::new(ctx.clone(),egui::ViewportId::ROOT,&window,Some(1.),None,None);let device=DeviceId::dummy();
for event in [WindowEvent::Focused(true),WindowEvent::CursorMoved{device_id:device,position:PhysicalPosition::new(400.,300.)},WindowEvent::MouseInput{device_id:device,state:ElementState::Pressed,button:MouseButton::Left},WindowEvent::ModifiersChanged(ModifiersState::CONTROL.into()),WindowEvent::CursorMoved{device_id:device,position:PhysicalPosition::new(400.,240.)},WindowEvent::ModifiersChanged(ModifiersState::empty().into())]{let start=state.egui_input().events.len();let _=state.on_window_event(&window,&event);if let Some(h)=&handle{h.lock().unwrap().record_appended(state.egui_input(),start);}}
let mut input=state.take_egui_input(&window);assert!(!input.modifiers.ctrl);input.time=Some(0.01);input.focused=true;input.screen_rect=Some(egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(800.,600.)));let count=input.events.len();if let Some(h)=&handle{h.lock().unwrap().begin_frame();}ui(&mut app,&ctx,input);if let Some(h)=&handle{h.lock().unwrap().begin_frame();}ui(&mut app,&ctx,egui::RawInput{screen_rect:Some(egui::Rect::from_min_size(egui::Pos2::ZERO,egui::vec2(800.,600.))),time:Some(0.05),focused:true,..Default::default()});rows.push(serde_json::json!({"name":if snapshots{"native-ingress-same-frame"}else{"final-state-only-negative"},"eye":app.camera.eye().to_array(),"forward":app.camera.forward().to_array(),"undo":app.undo_stack.len(),"emitted_egui_events":count,"frame_final_ctrl":false}));
}println!("{}",serde_json::json!({"cases":rows,"scope":"actual egui-winit State on native owned X11 window; controlled native CursorMoved/ModifiersChanged sequence, not real XTEST/coalescing or GPU proof"}));event_loop.exit();}
fn window_event(&mut self,_:&ActiveEventLoop,_:winit::window::WindowId,_:WindowEvent){}
}
pub fn run(){EventLoop::new().unwrap().run_app(&mut Probe).unwrap();}}
#[cfg(not(target_os="macos"))]fn main(){native::run();}
#[cfg(target_os="macos")]fn main(){eprintln!("Vulkan/X11 ingress diagnostic; native Metal ingress requires its own implementation and proof");std::process::exit(2);}
